const form=document.querySelector('#club-update');const list=document.querySelector('#draft-list');const status=document.querySelector('#form-status');function drafts(){try{return JSON.parse(localStorage.getItem('dedza-admin-drafts')||'[]')}catch{return[]}}function render(){if(!list)return;const rows=drafts();list.innerHTML=rows.length?rows.map(row=>`<article><strong>${row.headline}</strong><p>${row.summary}</p></article>`).join(''):'<p>No updates drafted yet.</p>'}form?.addEventListener('submit',event=>{event.preventDefault();const data=new FormData(form);const rows=drafts();rows.unshift({headline:String(data.get('headline')).trim(),summary:String(data.get('summary')).trim()});localStorage.setItem('dedza-admin-drafts',JSON.stringify(rows));form.reset();status.textContent='Draft saved in this browser.';render()});render();
